<script setup lang="ts">
import { api, friendlyError } from '@lostsky/api/client'
import { useQuery } from '@tanstack/vue-query'
import { ArrowLeft } from '@lucide/vue'
import { NButton } from 'naive-ui'
import { computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
const props=withDefaults(defineProps<{endpoint:string;title:string;staticParams?:Record<string,unknown>}>(),{staticParams:()=>({})});const route=useRoute();const router=useRouter();const params=computed(()=>({...props.staticParams,...(route.query.id?{id:route.query.id}:{})}));const query=useQuery({queryKey:computed(()=>['detail',props.endpoint,params.value]),queryFn:()=>api.get<Record<string,unknown>>(props.endpoint,params.value)});const display=(value:unknown)=>value==null?'—':typeof value==='object'?JSON.stringify(value):String(value)
</script>
<template><div class="detail"><NButton secondary class="back" @click="router.back()"><template #icon><ArrowLeft :size="18" /></template>返回</NButton><p v-if="query.isError.value" class="error" role="alert">{{friendlyError(query.error.value)}}</p><div v-else-if="query.isPending.value" class="loading"></div><section v-else class="sheet"><header><p>{{title}}</p><h2>{{query.data.value?.name??query.data.value?.title??title}}</h2></header><dl><template v-for="(value,key) in query.data.value" :key="key"><dt>{{key}}</dt><dd>{{display(value)}}</dd></template></dl></section></div></template>
<style scoped>.detail{display:grid;gap:1rem}.back{min-height:44px;width:fit-content;display:flex;align-items:center;gap:.4rem;padding:0 .25rem;color:var(--muted-ink);background:transparent;border:0}.sheet{background:white;border:1px solid var(--line);border-radius:10px;overflow:hidden}.sheet header{padding:1.25rem;background:var(--sky-night);color:white}.sheet header p{margin:0;color:var(--sky-lost);font-size:.75rem;font-weight:700}.sheet h2{margin:.35rem 0 0;font-size:1.4rem}dl{display:grid;grid-template-columns:minmax(5.5rem,.45fr) 1.55fr;margin:0;padding:1rem}dt,dd{margin:0;padding:.7rem 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}dt{color:var(--muted-ink);font-size:.8rem}dd{font-size:.88rem}.error{padding:1rem;color:var(--danger);background:white;border:1px solid var(--line);border-radius:8px}.loading{height:20rem;background:var(--line);border-radius:10px;opacity:.6}@media(min-width:760px){.sheet{max-width:56rem}.sheet header{padding:1.75rem}dl{padding:1.5rem 1.75rem}}</style>
